def init_pos(c):
    c.executescript('''
CREATE TABLE IF NOT EXISTS pos_credit_accounts(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('customer','employee')),employee TEXT UNIQUE,contact TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS pos_credit_ledger(id INTEGER PRIMARY KEY AUTOINCREMENT,account INTEGER NOT NULL REFERENCES pos_credit_accounts(id),amount INTEGER NOT NULL CHECK(amount!=0),balance INTEGER NOT NULL CHECK(balance>=0),at TEXT NOT NULL,actor TEXT NOT NULL,reason TEXT NOT NULL,sale INTEGER UNIQUE);
CREATE INDEX IF NOT EXISTS pos_credit_history ON pos_credit_ledger(account,id);
CREATE TRIGGER IF NOT EXISTS pos_credit_no_update BEFORE UPDATE ON pos_credit_ledger BEGIN SELECT RAISE(ABORT,'Credit history is immutable'); END;
CREATE TRIGGER IF NOT EXISTS pos_credit_no_delete BEFORE DELETE ON pos_credit_ledger BEGIN SELECT RAISE(ABORT,'Credit history is immutable'); END;
CREATE TABLE IF NOT EXISTS retail_theme_preferences(account TEXT PRIMARY KEY,theme TEXT NOT NULL,revision INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS retail_policies(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS retail_refunds(id INTEGER PRIMARY KEY,sale INTEGER NOT NULL REFERENCES pos_sales(id),body TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS retail_refunds_no_update BEFORE UPDATE ON retail_refunds BEGIN SELECT RAISE(ABORT,'Refund history is immutable'); END;
CREATE TRIGGER IF NOT EXISTS retail_refunds_no_delete BEFORE DELETE ON retail_refunds BEGIN SELECT RAISE(ABORT,'Refund history is immutable'); END;
CREATE TABLE IF NOT EXISTS retail_product_rules(id TEXT PRIMARY KEY REFERENCES pos_products(id),body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS retail_print_routes(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS retail_adjustments(id INTEGER PRIMARY KEY,cart TEXT NOT NULL,revision INTEGER NOT NULL,requested_by TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL,decided_by TEXT,decision_reason TEXT);
CREATE TABLE IF NOT EXISTS retail_sale_events(id INTEGER PRIMARY KEY,cart TEXT NOT NULL,at TEXT NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,body TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS retail_events_no_update BEFORE UPDATE ON retail_sale_events BEGIN SELECT RAISE(ABORT,'Sale history is immutable'); END;
CREATE TRIGGER IF NOT EXISTS retail_events_no_delete BEFORE DELETE ON retail_sale_events BEGIN SELECT RAISE(ABORT,'Sale history is immutable'); END;
CREATE TABLE IF NOT EXISTS retail_layouts(id TEXT PRIMARY KEY,revision INTEGER NOT NULL,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS retail_terminals(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE COLLATE NOCASE,device TEXT UNIQUE,layout TEXT REFERENCES retail_layouts(id),enabled INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL,hostname TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS pos_settings(id INTEGER PRIMARY KEY CHECK(id=1),body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pos_products(id TEXT PRIMARY KEY,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pos_carts(id TEXT PRIMARY KEY,owner TEXT NOT NULL,revision INTEGER NOT NULL,status TEXT NOT NULL,body TEXT NOT NULL,updated REAL NOT NULL);
CREATE TABLE IF NOT EXISTS pos_sales(id INTEGER PRIMARY KEY AUTOINCREMENT,cart TEXT UNIQUE NOT NULL,owner TEXT NOT NULL,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pos_operations(id TEXT PRIMARY KEY,owner TEXT NOT NULL,payload TEXT NOT NULL,result TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS pos_sales_no_update BEFORE UPDATE ON pos_sales BEGIN SELECT RAISE(ABORT,'Sales history is immutable'); END;
CREATE TRIGGER IF NOT EXISTS pos_sales_no_delete BEFORE DELETE ON pos_sales BEGIN SELECT RAISE(ABORT,'Sales history is immutable'); END;
''')

def pos_text(value,label,limit=120):
    if not isinstance(value,str) or not value.strip() or len(value.strip())>limit:raise Problem('Enter '+label+'.')
    return value.strip()

def pos_int(value,label,low=0,high=10000000):
    if type(value) is not int or not low<=value<=high:raise Problem('Invalid '+label+'.')
    return value

def pos_settings(c):
    row=c.execute('SELECT body FROM pos_settings WHERE id=1').fetchone()
    settings=json.loads(row[0]) if row else {'store':'','tax_bps':None,'currency':'USD'}
    settings['cash_rounding']=retail_policy(c)['cash_rounding']
    return settings

def pos_cart(row):
    return dict(id=row['id'],revision=row['revision'],status=row['status'],**json.loads(row['body']))

def pos_credit_account(c,ident):
    row=c.execute('SELECT a.*,p.name AS employee_name FROM pos_credit_accounts a LEFT JOIN receipt_profiles p ON p.profile_id=a.employee WHERE a.id=?',(ident,)).fetchone()
    if not row:raise Problem('Store-credit account not found.',404)
    result=dict(row);result['name']=result.pop('employee_name') or result['name']
    latest=c.execute('SELECT id,balance FROM pos_credit_ledger WHERE account=? ORDER BY id DESC LIMIT 1',(ident,)).fetchone()
    result.update(code='AC'+str(ident).zfill(6),revision=latest['id'] if latest else 0,balance=latest['balance'] if latest else 0)
    return result

def pos_credit_access(u,manage=False):
    if not has_permission(u,'manage_store_credit' if manage else 'use_store_credit') and (manage or not has_permission(u,'manage_store_credit')):raise Problem('Store-credit permission required.',403)

def retail_config(c):
    return {'layouts':[dict(id=r['id'],revision=r['revision'],**json.loads(r['body'])) for r in c.execute('SELECT * FROM retail_layouts ORDER BY rowid')], 'terminals':[dict(r) for r in c.execute('SELECT * FROM retail_terminals ORDER BY name COLLATE NOCASE')]}

# Retail workflow helpers are embedded into server.py for legacy updater compatibility.
def retail_rule(c,ident):
    row=c.execute('SELECT body FROM retail_product_rules WHERE id=?',(ident,)).fetchone()
    return json.loads(row[0]) if row else {'active':True,'modifiers':[],'components':[],'print_category':''}

def retail_product(c,row):
    body=json.loads(row['body']);rule=retail_rule(c,row['id'])
    revision=hashlib.sha256((row['body']+json.dumps(rule,sort_keys=True)).encode()).hexdigest()
    display=body['price'];now=time.time()
    if rule.get('promo_price') is not None and retail_epoch(rule['promo_from'],'promotion')<=now<retail_epoch(rule['promo_until'],'promotion'):display=rule['promo_price']
    return dict(body,id=row['id'],rules=rule,revision=revision,display_price=display)

def retail_epoch(value,label):
    if value in (None,''):return None
    if not isinstance(value,str):raise Problem('Invalid '+label+'.')
    try:
        stamp=dt.datetime.fromisoformat(value.replace('Z','+00:00'))
        if stamp.tzinfo is None:raise ValueError()
        return stamp.timestamp()
    except (ValueError,OverflowError):raise Problem('Use a date and time with a timezone for '+label+'.')

def retail_validate_product(c,d,bulk=False):
    if not isinstance(d,dict):raise Problem('Each product must contain valid fields.')
    body={'name':pos_text(d.get('name'),'a product name'),'category':pos_text(d.get('category'),'a category',60),'price':pos_int(d.get('price'),'price',1),'taxable':d.get('taxable')}
    if type(body['taxable']) is not bool:raise Problem('Choose taxable or non-taxable.')
    ident=d.get('id') or None;old=c.execute('SELECT * FROM pos_products WHERE id=?',(ident,)).fetchone() if ident else None
    if ident and not old:raise Problem('Product no longer exists.',409)
    if old and d.get('revision')!=retail_product(c,old)['revision']:raise Problem('Product changed. Reload its current values before saving.',409)
    rule=d.get('rules',retail_rule(c,ident) if ident else {})
    if not isinstance(rule,dict):raise Problem('Invalid product settings.')
    open_priced=rule.get('open_priced',False)
    if type(open_priced) is not bool:raise Problem('Choose Open Priced Item status.')
    active=rule.get('active',True)
    if type(active) is not bool:raise Problem('Choose active status.')
    clean={'active':active,'open_priced':open_priced,'print_category':str(rule.get('print_category','')).strip(),'modifiers':[],'components':[]}
    if len(clean['print_category'])>60:raise Problem('Printing category is too long.')
    for field in ('available_from','available_until','promo_from','promo_until'):
        stamp=retail_epoch(rule.get(field),field);clean[field]=rule.get(field) if stamp is not None else None
    for start,end in [('available_from','available_until'),('promo_from','promo_until')]:
        a=retail_epoch(clean[start],start);b=retail_epoch(clean[end],end)
        if a is not None and b is not None and a>=b:raise Problem('End time must be after start time.')
    clean['promo_price']=rule.get('promo_price')
    if clean['promo_price'] is not None:
        clean['promo_price']=pos_int(clean['promo_price'],'promotion price',1)
        if not clean['promo_from'] or not clean['promo_until']:raise Problem('Promotion needs a start and end time.')
    groups=rule.get('modifiers',[]);parts=rule.get('components',[])
    if open_priced and (parts or clean['promo_price'] is not None):raise Problem('Open Priced Items cannot use fixed-price bundles or promotion prices.')
    if not isinstance(groups,list) or len(groups)>12 or not isinstance(parts,list) or len(parts)>30:raise Problem('Too many choices or bundle components.')
    ids=set()
    for group in groups:
        if not isinstance(group,dict):raise Problem('Invalid choice group.')
        gid=pos_text(group.get('id'),'a choice identifier',64)
        if gid in ids:raise Problem('Duplicate choice group.')
        ids.add(gid);required=group.get('required',False)
        if type(required) is not bool:raise Problem('Choose whether a choice is required.')
        options=group.get('options')
        if not isinstance(options,list) or not 1<=len(options)<=30:raise Problem('Each choice group needs 1–30 options.')
        clean_options=[];option_ids=set()
        for option in options:
            if not isinstance(option,dict):raise Problem('Invalid option.')
            oid=pos_text(option.get('id'),'an option identifier',64)
            if oid in option_ids:raise Problem('Duplicate option.')
            option_ids.add(oid);clean_options.append({'id':oid,'name':pos_text(option.get('name'),'an option name',60),'price':pos_int(option.get('price'),'option price',0)})
        clean['modifiers'].append({'id':gid,'name':pos_text(group.get('name'),'a choice name',60),'required':required,'options':clean_options})
    part_ids=set()
    for part in parts:
        if not isinstance(part,dict):raise Problem('Invalid component.')
        pid=part.get('product');row=c.execute('SELECT * FROM pos_products WHERE id=?',(pid,)).fetchone() if isinstance(pid,str) else None
        if not row or pid==ident or pid in part_ids:raise Problem('Choose unique existing component products; a bundle cannot contain itself.')
        other=retail_rule(c,pid)
        if other.get('components') or other.get('modifiers') or other.get('open_priced'):raise Problem('Bundle components must be simple products without choices or nested bundles.')
        part_ids.add(pid);clean['components'].append({'product':pid,'quantity':pos_int(part.get('quantity'),'component quantity',1,99)})
    if parts and groups:raise Problem('Configure choices on individual products; bundles use fixed components.')
    if groups or parts or open_priced:
        for r in c.execute('SELECT id,body FROM retail_product_rules WHERE id<>?',(ident or '',)):
            if any(x['product']==ident for x in json.loads(r['body']).get('components',[])):raise Problem('This item is used in a bundle and must remain a simple product.')
    return ident,body,clean

def retail_available(rule,now=None):
    now=time.time() if now is None else now
    return rule.get('active',True) and (not rule.get('available_from') or retail_epoch(rule['available_from'],'availability')<=now) and (not rule.get('available_until') or now<retail_epoch(rule['available_until'],'availability'))

def retail_allocate(total,weights):
    if not weights:return []
    divisor=sum(weights)
    if divisor<=0:raise Problem('Bundle component prices must be positive.')
    amounts=[total*w//divisor for w in weights];left=total-sum(amounts)
    order=sorted(range(len(weights)),key=lambda i: (-(total*weights[i]%divisor),i))
    for i in order[:left]:amounts[i]+=1
    return amounts

def retail_sale_item(c,ident,choices,quantity,tax_bps,open_price=None):
    row=c.execute('SELECT * FROM pos_products WHERE id=?',(ident,)).fetchone()
    if not row:raise Problem('Item not found.',404)
    product=retail_product(c,row);rule=product['rules'];now=time.time()
    if not retail_available(rule,now):raise Problem('This product is not currently available.',409)
    price=product['price'];promotion=False
    if rule.get('open_priced'):price=pos_int(open_price,'open item price',1)
    elif open_price is not None:raise Problem('This product does not allow an entered price.')
    if rule.get('promo_price') is not None and retail_epoch(rule['promo_from'],'promotion')<=now<retail_epoch(rule['promo_until'],'promotion'):
        price=rule['promo_price'];promotion=True
    if not isinstance(choices,dict) or set(choices)-{g['id'] for g in rule.get('modifiers',[])}:raise Problem('Invalid item choices.')
    selected=[]
    for group in rule.get('modifiers',[]):
        oid=choices.get(group['id'])
        if not oid:
            if group['required']:raise Problem('Choose '+group['name']+'.')
            continue
        option=next((o for o in group['options'] if o['id']==oid),None)
        if not option:raise Problem('Invalid '+group['name']+' choice.')
        price+=option['price'];selected.append({'group':group['name'],'name':option['name'],'price':option['price']})
    if price>10000000:raise Problem('Item price exceeds the sale limit.')
    item={k:product[k] for k in ('name','category','taxable')};item.update(product=ident,price=price,quantity=quantity,subtotal=price*quantity,modifiers=selected,promotion=promotion,print_category=rule.get('print_category',''))
    if rule.get('open_priced'):item.update(open_priced=True,entered_price=open_price)
    parts=[]
    for part in rule.get('components',[]):
        p=c.execute('SELECT * FROM pos_products WHERE id=?',(part['product'],)).fetchone()
        if not p:raise Problem('Bundle component is unavailable.',409)
        component=retail_product(c,p)
        if not retail_available(component['rules'],now) or component['rules'].get('components') or component['rules'].get('modifiers') or component['rules'].get('open_priced'):raise Problem('Bundle component is unavailable or needs review in OFFICE.',409)
        parts.append({'product':p['id'],'name':component['name'],'quantity':part['quantity']*quantity,'weight':component['price']*part['quantity'],'taxable':component['taxable'],'print_category':component['rules'].get('print_category','')})
    if parts:
        amounts=retail_allocate(item['subtotal'],[p['weight'] for p in parts])
        for p,amount in zip(parts,amounts):p.update(subtotal=amount,tax=(amount*tax_bps+5000)//10000 if p['taxable'] else 0);p.pop('weight')
        item['components']=parts;item['tax']=sum(p['tax'] for p in parts)
    else:item['tax']=(item['subtotal']*tax_bps+5000)//10000 if item['taxable'] else 0
    return item

def retail_event(c,cart,actor,action,body):
    c.execute('INSERT INTO retail_sale_events(cart,at,actor,action,body) VALUES(?,?,?,?,?)',(cart,dt.datetime.now().astimezone().isoformat(timespec='seconds'),actor,action,json.dumps(body)))

def retail_save_cart(c,cart):
    cart['subtotal']=sum(x['subtotal'] for x in cart['lines']);cart['tax']=sum(x['tax'] for x in cart['lines']);cart['total']=cart['subtotal']+cart['tax']
    if not 0<=cart['total']<=10000000:raise Problem('Sale exceeds the supported amount.')
    cart['revision']+=1
    c.execute('UPDATE pos_carts SET body=?,revision=?,updated=? WHERE id=?',(json.dumps({k:v for k,v in cart.items() if k not in ('id','revision','status')}),cart['revision'],time.time(),cart['id']))

def retail_adjust(c,cart,request,actor):
    retail_check_adjustment(c,cart,request)
    mode=request['mode'];amount=request['amount'];index=request.get('index')
    lines=cart['lines']
    originals=cart.get('original_lines') or json.loads(json.dumps(lines))
    lines=json.loads(json.dumps(originals));targets=list(range(len(lines))) if index is None else [pos_int(index,'line number',0,len(lines)-1)]
    subtotal=sum(lines[i]['subtotal'] for i in targets)
    if mode=='discount' and amount>subtotal:raise Problem('Discount exceeds the selected subtotal.')
    allocations=retail_allocate(amount,[lines[i]['subtotal'] for i in targets]) if amount else [0]*len(targets)
    for i,part in zip(targets,allocations):
        line=lines[i];line['subtotal']+=part*(-1 if mode=='discount' else 1)
        if line.get('components'):
            shares=retail_allocate(line['subtotal'],[p['subtotal'] for p in originals[i]['components']])
            for component,share in zip(line['components'],shares):component['subtotal']=share;component['tax']=(share*cart['settings']['tax_bps']+5000)//10000 if component['taxable'] else 0
            line['tax']=sum(p['tax'] for p in line['components'])
        else:line['tax']=(line['subtotal']*cart['settings']['tax_bps']+5000)//10000 if line['taxable'] else 0
    cart['lines']=lines
    if amount:cart['original_lines']=originals;cart['adjustment']=dict(request,approved_by=actor)
    else:cart.pop('original_lines',None);cart.pop('adjustment',None)
    retail_save_cart(c,cart);retail_event(c,cart['id'],actor,'adjustment-approved',request)

def retail_workflow_get(c,u,path,query):
    if path=='catalog-config':
        if not has_permission(u,'manage_pos'):raise Problem('Manage POS permission required.',403)
        routes=c.execute('SELECT * FROM retail_print_routes WHERE id=1').fetchone()
        return {'products':[retail_product(c,r) for r in c.execute('SELECT * FROM pos_products ORDER BY rowid')],'routes':json.loads(routes['body']) if routes else [],'route_revision':routes['revision'] if routes else 0}
    if path=='held-sales':
        manager=has_permission(u,'transfer_pos_sales');rows=c.execute("SELECT c.*,p.name FROM pos_carts c LEFT JOIN receipt_profiles p ON p.profile_id=c.owner WHERE c.status='open'"+('' if manager else ' AND c.owner=?'),() if manager else (u['receipt_owner'],)).fetchall()
        return {'carts':[dict(pos_cart(r),employee=r['name'],owner=r['owner'],updated=r['updated']) for r in rows],'employees':[dict(r) for r in c.execute('SELECT p.profile_id AS id,p.name FROM receipt_profiles p JOIN users u ON u.name=p.name ORDER BY p.name')] if manager else []}
    if path=='approvals':
        if not has_permission(u,'approve_pos_adjustments'):raise Problem('Adjustment approval permission required.',403)
        return {'requests':[dict(r,body=json.loads(r['body'])) for r in c.execute("SELECT * FROM retail_adjustments WHERE status='pending' ORDER BY id") ]}
    if path=='sale-report':
        if not c.in_transaction:c.execute('BEGIN')
        if not has_permission(u,'view_pos_sales'):raise Problem('Sales report permission required.',403)
        start=retail_epoch(query.get('start',[''])[0],'report start');end=retail_epoch(query.get('end',[''])[0],'report end')
        if start is None or end is None or not 0<end-start<=366*86400:raise Problem('Choose a report range of up to 366 days.')
        sales=[];groups={};cashier=query.get('cashier',[''])[0];terminal=query.get('terminal',[''])[0]
        for row in c.execute('SELECT * FROM pos_sales ORDER BY id DESC'):
            sale=json.loads(row['body']);stamp=retail_epoch(sale['at'],'sale date')
            if not start<=stamp<end or (cashier and sale['cashier']!=cashier) or (terminal and sale.get('terminal','')!=terminal):continue
            sales.append(dict(id=row['id'],**sale))
            for line in sale['lines']:
                name=line['category'];g=groups.setdefault(name,{'category':name,'quantity':0,'subtotal':0,'tax':0});g['quantity']+=line['quantity'];g['subtotal']+=line['subtotal'];g['tax']+=line['tax']
        refunds=[]
        for row in c.execute('SELECT * FROM retail_refunds ORDER BY id DESC'):
            refund=json.loads(row['body']);original=c.execute('SELECT body FROM pos_sales WHERE id=?',(row['sale'],)).fetchone();original=json.loads(original[0])
            if start<=retail_epoch(refund['at'],'refund time')<end and (not cashier or refund['cashier']==cashier) and (not terminal or original.get('terminal','')==terminal):refunds.append(dict(id=row['id'],**refund))
        totals={'count':len(sales),'subtotal':sum(s['subtotal'] for s in sales),'tax':sum(s['tax'] for s in sales),'total':sum(s['total'] for s in sales),'store_credit':sum(s.get('store_credit',0) for s in sales),'cash':sum(s['tender']-s['change'] for s in sales),'cash_rounding':sum(s.get('cash_rounding',0) for s in sales),'refund_total':sum(r['total'] for r in refunds),'refund_cash':sum(r['cash'] for r in refunds),'refund_credit':sum(r['store_credit'] for r in refunds),'refund_tax':sum(r['tax'] for r in refunds),'refund_rounding':sum(r['cash_rounding'] for r in refunds)}
        totals['net_cash']=totals['cash']-totals['refund_cash'];totals['net_total']=totals['total']-totals['refund_total'];totals['net_tax']=totals['tax']-totals['refund_tax']
        return {'sales':sales,'refunds':refunds,'groups':list(groups.values()),'totals':totals}

    if path=='print-tickets':
        try:ident=int(query.get('sale',[''])[0])
        except ValueError:raise Problem('Choose a receipt.')
        row=c.execute('SELECT * FROM pos_sales WHERE id=?',(ident,)).fetchone()
        if not row or (row['owner']!=u['receipt_owner'] and not has_permission(u,'view_pos_sales')):raise Problem('Receipt not found.',404)
        sale=json.loads(row['body']);groups={};routes=c.execute('SELECT body FROM retail_print_routes WHERE id=1').fetchone();routes=json.loads(routes[0]) if routes else []
        for line in sale['lines']:
            for item in line.get('components') or [line]:
                category=item.get('print_category') or 'Receipt';groups.setdefault(category,[]).append(item)
        return {'sale':ident,'at':sale['at'],'cashier':sale['cashier'],'store':sale['settings']['store'],'tickets':[{'category':category,'printer':next((r['printer'] for r in routes if r['category']==category),''),'lines':lines} for category,lines in groups.items()]}
    return None

def retail_workflow_post(c,u,path,d,finish):
    if path in ('product-save','catalog-preview','catalog-import','print-routes'):
        if not has_permission(u,'manage_pos'):raise Problem('Manage POS permission required.',403)
        if path=='print-routes':
            old=c.execute('SELECT * FROM retail_print_routes WHERE id=1').fetchone();revision=old['revision'] if old else 0
            if d.get('revision')!=revision:raise Problem('Printing routes changed. Reload before saving.',409)
            routes=d.get('routes');clean=[];seen=set()
            if not isinstance(routes,list) or len(routes)>100:raise Problem('Use at most 100 printing categories.')
            for r in routes:
                if not isinstance(r,dict):raise Problem('Invalid route.')
                category=pos_text(r.get('category'),'a printing category',60);printer=pos_text(r.get('printer'),'a printer name',120)
                if category.casefold() in seen:raise Problem('Duplicate printing category.')
                seen.add(category.casefold());clean.append({'category':category,'printer':printer})
            c.execute('INSERT INTO retail_print_routes VALUES(1,?,?) ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,body=excluded.body',(revision+1,json.dumps(clean)))
            return finish({'revision':revision+1},'Printing routes saved')
        rows=[d] if path=='product-save' else d.get('rows')
        if not isinstance(rows,list) or not 1<=len(rows)<=500:raise Problem('Use between 1 and 500 products per import.')
        normalized=[retail_validate_product(c,r) for r in rows];ids=[r[0] for r in normalized if r[0]]
        if len(set(ids))!=len(ids):raise Problem('A product appears more than once.')
        # Validate the complete proposed batch, not only the old component definitions.
        proposed={ident:rule for ident,body,rule in normalized if ident}
        for ident,body,rule in normalized:
            for part in rule.get('components',[]):
                component=proposed.get(part['product'],retail_rule(c,part['product']))
                if component.get('components') or component.get('modifiers'):raise Problem('A bundle component must remain a simple product.')
        if path=='catalog-preview':return finish({'rows':[dict(body,id=ident,revision=rows[i].get('revision'),rules=rule) for i,(ident,body,rule) in enumerate(normalized)],'create':sum(not r[0] for r in normalized),'update':sum(bool(r[0]) for r in normalized)},'Catalog import validated')
        if path=='catalog-import' and d.get('confirmed') is not True:raise Problem('Preview and confirm the import first.')
        saved=[]
        for ident,body,rule in normalized:
            ident=ident or secrets.token_hex(16);c.execute('INSERT INTO pos_products VALUES(?,?) ON CONFLICT(id) DO UPDATE SET body=excluded.body',(ident,json.dumps(body)))
            c.execute('INSERT INTO retail_product_rules VALUES(?,?) ON CONFLICT(id) DO UPDATE SET body=excluded.body',(ident,json.dumps(rule)));saved.append(ident)
        return finish({'ids':saved},'Retail catalog saved: '+str(len(saved))+' products')
    if path=='transfer-sale':
        if not has_permission(u,'transfer_pos_sales'):raise Problem('Transfer held sales permission required.',403)
        row=c.execute("SELECT * FROM pos_carts WHERE id=? AND status='open'",(d.get('cart'),)).fetchone()
        if not row:raise Problem('Open sale not found.',404)
        cart=pos_cart(row)
        if row['revision']!=d.get('revision') or not cart.get('held'):raise Problem('Sale changed or is not held. Refresh before transferring.',409)
        target=c.execute('SELECT p.profile_id,p.name FROM receipt_profiles p JOIN users u ON u.name=p.name WHERE p.profile_id=?',(d.get('owner'),)).fetchone()
        if not target:raise Problem('Choose a current employee.')
        person=c.execute('SELECT admin FROM users WHERE name=?',(target['name'],)).fetchone()
        role=c.execute('SELECT r.body FROM permission_roles r JOIN user_roles a ON a.role_id=r.id WHERE a.name=?',(target['name'],)).fetchone()
        grants=role or c.execute('SELECT body FROM user_grants WHERE name=?',(target['name'],)).fetchone()
        if not person['admin'] and (not grants or not json.loads(grants[0]).get('use_pos')):raise Problem('Choose an employee with Point of Sale access.')
        reason=pos_text(d.get('reason'),'a transfer reason',300)
        c.execute('UPDATE pos_carts SET owner=?,revision=revision+1,updated=? WHERE id=?',(target['profile_id'],time.time(),row['id']))
        retail_event(c,row['id'],u['name'],'transfer',{'from':row['owner'],'to':target['profile_id'],'reason':reason})
        return finish({'ok':True},'Held sale transferred to '+target['name'])
    if path=='adjustment-decision':
        if not has_permission(u,'approve_pos_adjustments'):raise Problem('Adjustment approval permission required.',403)
        request=c.execute("SELECT * FROM retail_adjustments WHERE id=? AND status='pending'",(d.get('id'),)).fetchone()
        if not request:raise Problem('Pending request not found.',409)
        decision=d.get('decision')
        if decision not in ('approved','denied'):raise Problem('Choose approve or deny.')
        reason=pos_text(d.get('reason'),'a decision reason',300)
        if decision=='approved':
            row=c.execute("SELECT * FROM pos_carts WHERE id=? AND status='open'",(request['cart'],)).fetchone()
            if not row or row['revision']!=request['revision']:raise Problem('Sale changed. Deny this request and ask the cashier to resubmit.',409)
            retail_adjust(c,pos_cart(row),json.loads(request['body']),u['name'])
        c.execute('UPDATE retail_adjustments SET status=?,decided_by=?,decision_reason=? WHERE id=?',(decision,u['name'],reason,request['id']))
        retail_event(c,request['cart'],u['name'],'adjustment-'+decision,{'request':request['id'],'reason':reason})
        return finish({'ok':True},'Adjustment '+decision)
    return None


def retail_policy(c):
    defaults={'cash_rounding':'off','max_discount_bps':2000,'max_surcharge_bps':1000,'discount_categories':[],'exclude_promotions':True,'return_days':30}
    row=c.execute('SELECT * FROM retail_policies WHERE id=1').fetchone()
    if row:defaults.update(json.loads(row['body']))
    return dict(defaults,revision=row['revision'] if row else 0)

def retail_cash_change(settings,tender,due):
    exact=tender-due
    change=((exact+2)//5)*5 if due and settings.get('cash_rounding')=='nearest5' else exact
    return {'change':change,'exact_change':exact,'cash_rounding':exact-change,'cash_paid':tender-change}

def retail_check_adjustment(c,cart,request):
    policy=retail_policy(c);lines=cart.get('original_lines') or cart['lines'];index=request.get('index')
    targets=lines if index is None else [lines[pos_int(index,'line number',0,len(lines)-1)]]
    subtotal=sum(l['subtotal'] for l in targets)
    if request.get('percent_bps') is not None:request['amount']=(subtotal*pos_int(request['percent_bps'],'percentage',0,10000)+5000)//10000
    if request['amount']:
        limit=policy['max_discount_bps'] if request['mode']=='discount' else policy['max_surcharge_bps']
        if request['amount']>(subtotal*limit+5000)//10000:raise Problem('Adjustment exceeds the configured '+str(limit/100)+'% limit.')
        if request['mode']=='discount':
            if policy['discount_categories'] and any(l['category'] not in policy['discount_categories'] for l in targets):raise Problem('Select a line in an eligible discount category.')
            if policy['exclude_promotions'] and any(l.get('promotion') for l in targets):raise Problem('Promotional items cannot receive another discount.')
    request['policy_revision']=policy['revision']

def retail_refund_state(c,sale_id):
    rows=[dict(id=r['id'],**json.loads(r['body'])) for r in c.execute('SELECT * FROM retail_refunds WHERE sale=? ORDER BY id',(sale_id,))]
    return rows

def retail_refund_preview(c,u,d):
    if not has_permission(u,'refund_pos_sales'):raise Problem('Refund permission required.',403)
    ident=pos_int(d.get('sale'),'receipt number',1);row=c.execute('SELECT * FROM pos_sales WHERE id=?',(ident,)).fetchone()
    if not row:raise Problem('Receipt not found.',404)
    sale=json.loads(row['body']);policy=retail_policy(c)
    if d.get('policy_revision')!=policy['revision']:raise Problem('Return rules changed. Reload this receipt before continuing.',409)
    if policy['return_days'] and time.time()-retail_epoch(sale['at'],'sale time')>policy['return_days']*86400:raise Problem('This receipt is outside the configured return window.')
    history=retail_refund_state(c,ident)
    if d.get('refund_revision')!=len(history):raise Problem('This receipt has another return. Refresh before continuing.',409)
    selected=d.get('lines');reason=pos_text(d.get('reason'),'a refund reason',300)
    if not isinstance(selected,list) or not selected:raise Problem('Select items to return.')
    already={};subtotal=tax=0;lines=[];seen=set()
    for refund in history:
        for line in refund['lines']:already[line['index']]=already.get(line['index'],0)+line['quantity']
    for item in selected:
        if not isinstance(item,dict):raise Problem('Invalid returned item.')
        index=pos_int(item.get('index'),'line number',0,len(sale['lines'])-1)
        if index in seen:raise Problem('Duplicate returned line.')
        seen.add(index);original=sale['lines'][index];prior=already.get(index,0);qty=pos_int(item.get('quantity'),'return quantity',1,original['quantity']-prior)
        # Cumulative allocation returns every cent exactly once on a full return.
        net=original['subtotal']*(prior+qty)//original['quantity']-original['subtotal']*prior//original['quantity']
        line_tax=original['tax']*(prior+qty)//original['quantity']-original['tax']*prior//original['quantity']
        lines.append({'index':index,'name':original['name'],'category':original['category'],'quantity':qty,'subtotal':net,'tax':line_tax});subtotal+=net;tax+=line_tax
    total=subtotal+tax;prior_total=sum(r['total'] for r in history);cumulative=prior_total+total
    if cumulative>sale['total']:raise Problem('Return exceeds the original receipt.',409)
    credit_original=sale.get('store_credit',0);cash_original=sale['tender']-sale['change']
    credit_target=cumulative*credit_original//sale['total'] if sale['total'] else 0
    raw_cash=cumulative-credit_target
    cash_target=((raw_cash+2)//5)*5 if sale['settings'].get('cash_rounding')=='nearest5' and cash_original else raw_cash
    if cumulative==sale['total']:cash_target=cash_original;credit_target=credit_original
    cash_target=min(cash_target,cash_original)
    cash=cash_target-sum(r['cash'] for r in history);credit=credit_target-sum(r['store_credit'] for r in history)
    if cash<0 or credit<0:raise Problem('Return allocations need administrator review.',409)
    account=None
    if credit:
        code=sale.get('credit_account','')
        if not re.fullmatch('AC[0-9]+',code):raise Problem('Original store-credit account cannot be found.',409)
        account=pos_credit_account(c,int(code[2:]))
        if account['balance']+credit>10000000:raise Problem('Return would exceed the store-credit account limit.')
    result={'sale':ident,'cashier':u['name'],'reason':reason,'lines':lines,'subtotal':subtotal,'tax':tax,'total':total,'cash':cash,'store_credit':credit,'cash_rounding':cash+credit-total,'credit_account':sale.get('credit_account'),'refund_revision':len(history),'policy_revision':policy['revision'],'store':sale['settings']['store'],'original_at':sale['at']}
    return result,account

def retail_finance_get(c,u,path,query):
    if path=='policies':
        if not has_permission(u,'manage_pos'):raise Problem('Manage POS permission required.',403)
        return {'policy':retail_policy(c)}
    if path=='refund-receipt':
        if not has_permission(u,'refund_pos_sales'):raise Problem('Refund permission required.',403)
        try:ident=int(query.get('sale',[''])[0])
        except ValueError:raise Problem('Enter a receipt number.')
        row=c.execute('SELECT * FROM pos_sales WHERE id=?',(ident,)).fetchone()
        if not row:raise Problem('Receipt not found.',404)
        return {'sale':dict(id=ident,**json.loads(row['body'])),'refunds':retail_refund_state(c,ident),'policy':retail_policy(c)}
    if path=='sale-events':
        ident=query.get('cart',[''])[0];row=c.execute('SELECT owner FROM pos_carts WHERE id=?',(ident,)).fetchone()
        if not row or (row['owner']!=u['receipt_owner'] and not has_permission(u,'view_pos_sales')):raise Problem('Sale not found.',404)
        return {'events':[dict(r,body=json.loads(r['body'])) for r in c.execute('SELECT * FROM retail_sale_events WHERE cart=? ORDER BY id',(ident,))]}
    return None

def retail_finance_post(c,u,path,d,finish):
    if path=='policies-save':
        if not has_permission(u,'manage_pos'):raise Problem('Manage POS permission required.',403)
        old=retail_policy(c)
        if d.get('revision')!=old['revision']:raise Problem('Rules changed. Reload before saving.',409)
        mode=d.get('cash_rounding')
        if mode not in ('off','nearest5'):raise Problem('Choose a cash rounding option.')
        categories=d.get('discount_categories')
        if not isinstance(categories,list) or len(categories)>100 or any(not isinstance(x,str) or not x.strip() or len(x)>60 for x in categories):raise Problem('Invalid discount categories.')
        exclude=d.get('exclude_promotions')
        if type(exclude) is not bool:raise Problem('Choose the promotion discount rule.')
        body={'cash_rounding':mode,'max_discount_bps':pos_int(d.get('max_discount_bps'),'discount limit',0,10000),'max_surcharge_bps':pos_int(d.get('max_surcharge_bps'),'surcharge limit',0,10000),'discount_categories':list(dict.fromkeys(x.strip() for x in categories)),'exclude_promotions':exclude,'return_days':pos_int(d.get('return_days'),'return days',0,3650)}
        c.execute('INSERT INTO retail_policies VALUES(1,?,?) ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,body=excluded.body',(old['revision']+1,json.dumps(body)))
        return finish({'policy':dict(body,revision=old['revision']+1)},'Retail cash, discount and return rules saved')
    if path in ('refund-preview','refund'):
        result,account=retail_refund_preview(c,u,d)
        if path=='refund-preview':return finish({'preview':result},'Return previewed for receipt #'+str(result['sale']))
        if d.get('confirmed') is not True:raise Problem('Preview and confirm the return first.')
        result['at']=dt.datetime.now().astimezone().isoformat(timespec='seconds')
        refund=c.execute('INSERT INTO retail_refunds(sale,body) VALUES(?,?)',(result['sale'],json.dumps(result))).lastrowid
        if account:
            c.execute('INSERT INTO pos_credit_ledger(account,amount,balance,at,actor,reason,sale) VALUES(?,?,?,?,?,?,NULL)',(account['id'],result['store_credit'],account['balance']+result['store_credit'],result['at'],u['name'],'Refund #'+str(refund)+' for receipt #'+str(result['sale'])))
        cart=c.execute('SELECT cart FROM pos_sales WHERE id=?',(result['sale'],)).fetchone()[0]
        retail_event(c,cart,u['name'],'refund',{'refund':refund,**result})
        return finish({'refund':dict(id=refund,**result)},'Refund #'+str(refund)+' saved for receipt #'+str(result['sale']))
    return None


RETAIL_THEMES=('classic-gray','harbor-blue','coastal-teal','midnight','coastyouth-red')
def retail_theme(c,u):
    account=u.get('receipt_owner') or 'user:'+u['name']
    row=c.execute('SELECT * FROM retail_theme_preferences WHERE account=?',(account,)).fetchone()
    default=c.execute("SELECT * FROM retail_theme_preferences WHERE account='store'").fetchone()
    return {'theme':row['theme'] if row else 'default','revision':row['revision'] if row else 0,'default':default['theme'] if default else 'harbor-blue','default_revision':default['revision'] if default else 0}

def pos_get(handler,c,u,path,query):
    if not has_permission(u,'use_pos'):raise Problem('Point of Sale permission required.',403)
    owner=u.get('receipt_owner')
    result=retail_finance_get(c,u,path,query)
    if result is not None:return handler.send(result)
    result=retail_workflow_get(c,u,path,query)
    if result is not None:return handler.send(result)
    if path in ('accounts','account'):
        pos_credit_access(u)
        if path=='account':
            try:ident=int(query.get('id',[''])[0]);before=int(query.get('before',['9223372036854775807'])[0])
            except (ValueError,TypeError):raise Problem('Invalid account identifier.')
            account=pos_credit_account(c,ident)
            history=[dict(r) for r in c.execute('SELECT * FROM pos_credit_ledger WHERE account=? AND id<? ORDER BY id DESC LIMIT 101',(ident,before))]
            return handler.send({'account':account,'history':history[:100],'more':len(history)>100})
        search=str(query.get('search',[''])[0]).strip().casefold()
        accounts=[pos_credit_account(c,r[0]) for r in c.execute('SELECT id FROM pos_credit_accounts ORDER BY name COLLATE NOCASE')]
        accounts=[a for a in accounts if search in (a['name']+' '+a['code']+' '+a['contact']).casefold()]
        employees=[dict(r) for r in c.execute('SELECT p.profile_id AS id,p.name FROM receipt_profiles p JOIN users u ON u.name=p.name ORDER BY p.name')]
        return handler.send({'accounts':accounts,'employees':employees})
    if path=='retail-config':
        if not has_permission(u,'manage_pos'):raise Problem('Manage POS permission required.',403)
        return handler.send(retail_config(c))
    if path=='terminal':
        device=query.get('device',[''])[0]
        row=c.execute('SELECT * FROM retail_terminals WHERE device=?',(device,)).fetchone()
        terminal=dict(row) if row else None
        layout=c.execute('SELECT body FROM retail_layouts WHERE id=?',(row['layout'],)).fetchone() if row and row['enabled'] else None
        return handler.send({'terminal':terminal,'layout':json.loads(layout[0]) if layout else None})
    if path=='overview':
        return handler.send({'settings':pos_settings(c),'products':[dict(retail_product(c,r),available=retail_available(retail_rule(c,r['id']))) for r in c.execute('SELECT * FROM pos_products ORDER BY rowid')],
            'carts':[pos_cart(r) for r in c.execute("SELECT * FROM pos_carts WHERE owner=? AND status='open' ORDER BY updated DESC LIMIT 100",(owner,))]})
    if path=='sales':
        scope='' if has_permission(u,'view_pos_sales') else 'WHERE owner=?'
        return handler.send({'sales':[dict(id=r['id'],**json.loads(r['body'])) for r in c.execute('SELECT * FROM pos_sales '+scope+' ORDER BY id DESC LIMIT 100',() if not scope else (owner,))]})
    raise Problem('Not found.',404)

# POS update coordination lives outside the operational database.
POS_UPDATE_DEVICES={}
POS_UPDATE_RELEASE={'checking':False}
def pos_update_read():
    path=DATA/'pos-update-control.json'
    if not path.exists():return {'seconds':120,'campaign':None}
    try:return json.loads(path.read_text(encoding='utf-8'))
    except Exception:raise Problem('POS update settings cannot be read; no update was authorized.',500)
def pos_update_save(value):
    path=DATA/'pos-update-control.json';temp=path.with_suffix('.tmp')
    temp.write_text(json.dumps(value),encoding='utf-8');os.replace(temp,path)
def pos_update_check():
    global POS_UPDATE_RELEASE
    try:
        repository='m404ntfd/mgc-yfc-operations'
        release=json.loads(updater.fetch('https://api.github.com/repos/'+repository+'/releases/latest',1000000))
        if release.get('draft') or release.get('prerelease'):raise ValueError('A stable release is required.')
        candidates=[]
        for asset in release.get('assets',[]):
            match=re.fullmatch(r'MGC-YFC-POS-Setup-v(\d+\.\d+\.\d+)\.exe',asset.get('name',''))
            if match and re.fullmatch(r'sha256:[a-f0-9]{64}',asset.get('digest') or ''):candidates.append((updater.version(match[1]),match[1],asset))
        if not candidates:raise ValueError('No verified POS installer is available.')
        _,version,asset=max(candidates)
        if not asset['browser_download_url'].startswith('https://github.com/'+repository+'/releases/download/'):raise ValueError('Unexpected installer address.')
        with LOCK:POS_UPDATE_RELEASE={'checking':False,'version':version,'url':asset['browser_download_url'],'checked':time.time()}
    except Exception as e:
        with LOCK:POS_UPDATE_RELEASE={'checking':False,'error':str(e)}
def pos_update_state(u):
    settings=pos_update_read();result={'seconds':settings['seconds'],'campaign':settings.get('campaign')}
    if u.get('admin'):result.update(release=POS_UPDATE_RELEASE,devices=list(POS_UPDATE_DEVICES.values()))
    return result
def pos_update_post(handler,u,path,d):
    global POS_UPDATE_RELEASE
    if path=='heartbeat':
        device=d.get('device','');version=d.get('version','')
        if not re.fullmatch('[a-f0-9]{32}',str(device)) or not re.fullmatch(r'\d+\.\d+\.\d+',str(version)):raise Problem('Invalid POS device.')
        if not has_permission(u,'use_pos') and not u.get('admin'):raise Problem('POS access required.',403)
        for key,row in list(POS_UPDATE_DEVICES.items()):
            if row['seen']<time.time()-86400:POS_UPDATE_DEVICES.pop(key,None)
        POS_UPDATE_DEVICES[device]={'device':device,'version':version,'user':u['name'],'seen':time.time(),'status':str(d.get('status','Connected'))[:200],'updater':d.get('updater') is True}
        return handler.send(pos_update_state(u))
    if not u.get('admin'):raise Problem('Administrator access required.',403)
    settings=pos_update_read()
    if path=='check':
        if not POS_UPDATE_RELEASE.get('checking'):
            POS_UPDATE_RELEASE={'checking':True};threading.Thread(target=pos_update_check,daemon=True).start()
    elif path=='settings':
        seconds=d.get('seconds')
        if type(seconds) is not int or not 30<=seconds<=3600:raise Problem('Choose 30 to 3600 whole seconds.')
        settings['seconds']=seconds;pos_update_save(settings)
    elif path=='start':
        release=POS_UPDATE_RELEASE
        if release.get('checking') or not release.get('version') or time.time()-release.get('checked',0)>600:raise Problem('Check for POS updates first.',409)
        if settings.get('campaign'):raise Problem('Cancel the current POS update request before starting another.',409)
        target=d.get('target','all')
        if target!='all' and target not in POS_UPDATE_DEVICES:raise Problem('Select a connected POS computer.')
        settings['campaign']={'id':secrets.token_hex(32),'version':release['version'],'seconds':settings['seconds'],'target':target,'by':u['name'],'at':time.time()};pos_update_save(settings)
    elif path=='cancel':settings['campaign']=None;pos_update_save(settings)
    else:raise Problem('Unknown POS update action.',404)
    return handler.send(pos_update_state(u))


POS_KIOSK_APPROVALS={}

def pos_kiosk_approval(c,u,d):
    if not u.get('admin'):raise Problem('An Operations administrator must approve exit-passcode changes.',403)
    device=d.get('device');nonce=d.get('nonce')
    if not isinstance(device,str) or not re.fullmatch('[0-9a-f]{32}',device) or not isinstance(nonce,str) or not re.fullmatch('[0-9a-f]{64}',nonce):raise Problem('Invalid checkout-computer request.')
    now=time.time()
    for key in list(POS_KIOSK_APPROVALS):
        if POS_KIOSK_APPROVALS[key]['expires']<now:POS_KIOSK_APPROVALS.pop(key,None)
    if len(POS_KIOSK_APPROVALS)>=500:raise Problem('Too many pending approvals. Try again shortly.',429)
    token=secrets.token_hex(32)
    POS_KIOSK_APPROVALS[hashlib.sha256(token.encode()).hexdigest()]={'device':device,'nonce':nonce,'name':u['name'],'expires':now+60}
    return {'token':token}

def pos_kiosk_redeem(c,d):
    token=d.get('token')
    if not isinstance(token,str) or not re.fullmatch('[0-9a-f]{64}',token):raise Problem('Invalid administrator approval.',403)
    key=hashlib.sha256(token.encode()).hexdigest();approval=POS_KIOSK_APPROVALS.get(key)
    if not approval or approval['expires']<time.time() or approval['device']!=d.get('device') or approval['nonce']!=d.get('nonce'):raise Problem('Administrator approval expired or belongs to another checkout computer.',403)
    POS_KIOSK_APPROVALS.pop(key,None)
    row=c.execute('SELECT admin FROM users WHERE name=?',(approval['name'],)).fetchone()
    if not row or not row['admin']:raise Problem('Administrator access is no longer available.',403)
    c.execute('INSERT INTO audit VALUES(?,?,?,?)',(dt.datetime.now().isoformat(timespec='seconds'),approval['name'],'Authorized POS exit-passcode setup/change on device '+approval['device'],''))
    c.commit()
    return {'admin':True,'device':approval['device'],'nonce':approval['nonce']}

def pos_post(handler,c,u,path,d):
    if path=='kiosk-approval':return handler.send(pos_kiosk_approval(c,u,d))
    if not has_permission(u,'use_pos'):raise Problem('Point of Sale permission required.',403)
    owner=u.get('receipt_owner')
    if not owner:raise Problem('Employee account required.',403)
    operation=d.get('request')
    if not isinstance(operation,str) or not re.fullmatch('[0-9a-f]{32}',operation):raise Problem('A unique request is required.')
    payload=json.dumps([path,d],sort_keys=True,separators=(',',':'))
    previous=c.execute('SELECT * FROM pos_operations WHERE id=?',(operation,)).fetchone()
    if previous:
        if previous['owner']!=owner or previous['payload']!=payload:raise Problem('Request already used for another action.',409)
        return handler.send(json.loads(previous['result']))
    now=dt.datetime.now().astimezone().isoformat(timespec='seconds')
    def finish(result,action):
        c.execute('INSERT INTO pos_operations VALUES(?,?,?,?)',(operation,owner,payload,json.dumps(result)))
        c.execute('INSERT INTO audit VALUES(?,?,?,?)',(now,u['name'],action,''))
        c.commit()
        return handler.send(result)
    if path in ('policies-save','refund-preview','refund'):
        return retail_finance_post(c,u,path,d,finish)
    if path in ('product-save','catalog-preview','catalog-import','print-routes','transfer-sale','adjustment-decision'):
        return retail_workflow_post(c,u,path,d,finish)
    if path in ('layout-save','terminal-save'):
        if not has_permission(u,'manage_pos'):raise Problem('Manage POS permission required.',403)
        ident=d.get('id') or secrets.token_hex(16)
        if not isinstance(ident,str) or not re.fullmatch('[0-9a-f]{32}',ident):raise Problem('Invalid identifier.')
        table='retail_layouts' if path=='layout-save' else 'retail_terminals'
        old=c.execute('SELECT * FROM '+table+' WHERE id=?',(ident,)).fetchone()
        if d.get('revision',0)!=(old['revision'] if old else 0):raise Problem('Changed by another administrator. Reopen this editor before saving.',409)
        revision=(old['revision'] if old else 0)+1
        if path=='layout-save':
            body={'name':pos_text(d.get('name'),'a layout name',80),'columns':pos_int(d.get('columns'),'columns',2,6),'groups':[]}
            groups=d.get('groups')
            if not isinstance(groups,list) or not 1<=len(groups)<=30:raise Problem('Use between 1 and 30 groups.')
            products={r[0] for r in c.execute('SELECT id FROM pos_products')}
            for group in groups:
                if not isinstance(group,dict):raise Problem('Invalid group.')
                color=group.get('color','')
                if not isinstance(color,str) or not re.fullmatch('#[0-9a-fA-F]{6}',color):raise Problem('Choose a button color.')
                items=group.get('products')
                if not isinstance(items,list) or len(items)>200 or any(not isinstance(x,str) or x not in products for x in items) or len(set(items))!=len(items):raise Problem('Choose unique catalog products.')
                body['groups'].append({'name':pos_text(group.get('name'),'a group name',60),'color':color,'products':items})
            c.execute('INSERT INTO retail_layouts VALUES(?,?,?) ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,body=excluded.body',(ident,revision,json.dumps(body)))
        else:
            name=pos_text(d.get('name'),'a terminal name',60)
            device=d.get('device') or None
            if device and (not isinstance(device,str) or not re.fullmatch('[0-9a-f]{32}',device)):raise Problem('Invalid device identity.')
            layout=d.get('layout') or None
            if layout and not c.execute('SELECT 1 FROM retail_layouts WHERE id=?',(layout,)).fetchone():raise Problem('Choose an existing layout.')
            if type(d.get('enabled')) is not bool:raise Problem('Choose terminal status.')
            if old and old['device'] and device!=old['device']:raise Problem('A registered device cannot be reassigned. Disable the old terminal and register a new one.',409)
            if c.execute('SELECT 1 FROM retail_terminals WHERE id<>? AND (name=? COLLATE NOCASE OR (device IS NOT NULL AND device=?))',(ident,name,device)).fetchone():raise Problem('That terminal name or device is already registered.',409)
            hostname=d.get('hostname','')
            if not isinstance(hostname,str) or len(hostname)>120:raise Problem('Invalid computer name.')
            c.execute('INSERT INTO retail_terminals VALUES(?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,device=excluded.device,layout=excluded.layout,enabled=excluded.enabled,revision=excluded.revision,hostname=excluded.hostname',(ident,name,device,layout,int(d['enabled']),revision,hostname))
        return finish({'id':ident,'revision':revision},'Retail '+path+' '+ident)
    if path in ('account-create','account-adjust'):
        pos_credit_access(u,True)
        if path=='account-create':
            kind=d.get('kind')
            if kind not in ('customer','employee'):raise Problem('Choose customer or employee.')
            employee=None;name=pos_text(d.get('name'),'an account name')
            if kind=='employee':
                employee=pos_text(d.get('employee'),'an employee',64)
                profile=c.execute('SELECT p.name FROM receipt_profiles p JOIN users u ON u.name=p.name WHERE p.profile_id=?',(employee,)).fetchone()
                if not profile:raise Problem('Choose a current employee.')
                if c.execute('SELECT 1 FROM pos_credit_accounts WHERE employee=?',(employee,)).fetchone():raise Problem('This employee already has a store-credit account.',409)
                name=profile['name']
            contact=d.get('contact','')
            if not isinstance(contact,str) or len(contact)>200:raise Problem('Contact/reference must be at most 200 characters.')
            ident=c.execute('INSERT INTO pos_credit_accounts(name,kind,employee,contact) VALUES(?,?,?,?)',(name,kind,employee,contact.strip())).lastrowid
        else:
            ident=pos_int(d.get('account'),'account',1);account=pos_credit_account(c,ident)
            if d.get('account_revision')!=account['revision']:raise Problem('Balance changed. Refresh the account before adjusting.',409)
            amount=pos_int(d.get('amount'),'adjustment amount',1)
            if d.get('direction') not in ('add','subtract'):raise Problem('Choose add or subtract.')
            amount*=1 if d['direction']=='add' else -1
            balance=account['balance']+amount
            if not 0<=balance<=10000000:raise Problem('Balance must remain between $0 and $100,000.')
            reason=pos_text(d.get('reason'),'an adjustment reason/reference',500)
            c.execute('INSERT INTO pos_credit_ledger(account,amount,balance,at,actor,reason) VALUES(?,?,?,?,?,?)',(ident,amount,balance,now,u['name'],reason))
        return finish({'account':pos_credit_account(c,ident)},'Store-credit '+path+' AC'+str(ident).zfill(6))
    if path=='settings':
        if not has_permission(u,'manage_pos'):raise Problem('Manage POS permission required.',403)
        if d.get('confirmed') is not True:raise Problem('Confirm the store tax rate before enabling checkout.')
        settings={'store':pos_text(d.get('store'),'a receipt store name'),'tax_bps':pos_int(d.get('tax_bps'),'tax rate',0,10000),'currency':'USD'}
        c.execute('INSERT OR REPLACE INTO pos_settings VALUES(1,?)',(json.dumps(settings),))
        return finish({'settings':settings},'POS settings saved')
    if path=='product':
        if not has_permission(u,'manage_pos'):raise Problem('Manage POS permission required.',403)
        product={'name':pos_text(d.get('name'),'an item name'),'category':pos_text(d.get('category'),'a category',60),'price':pos_int(d.get('price'),'price',1),'taxable':d.get('taxable')}
        if type(product['taxable']) is not bool:raise Problem('Choose taxable or non-taxable.')
        ident=secrets.token_hex(16)
        c.execute('INSERT INTO pos_products VALUES(?,?)',(ident,json.dumps(product)))
        return finish({'product':dict(id=ident,**product)},'POS catalog item added')
    if path=='new':
        settings=pos_settings(c)
        if settings['tax_bps'] is None:raise Problem('An administrator must configure POS tax and receipt settings first.',409)
        terminal=c.execute('SELECT name,enabled FROM retail_terminals WHERE device=?',(d.get('device',''),)).fetchone()
        if terminal and not terminal['enabled']:raise Problem('This terminal is disabled.',403)
        ident=secrets.token_hex(16);body={'lines':[],'subtotal':0,'tax':0,'total':0,'settings':settings,'terminal':terminal['name'] if terminal else '', 'held':False}
        c.execute('INSERT INTO pos_carts VALUES(?,?,1,?,?,?)',(ident,owner,'open',json.dumps(body),time.time()))
        return finish({'cart':dict(id=ident,revision=1,status='open',**body)},'POS cart started')
    ident=pos_text(d.get('cart'),'a cart identifier',32)
    row=c.execute('SELECT * FROM pos_carts WHERE id=? AND owner=?',(ident,owner)).fetchone()
    if not row:raise Problem('Cart not found.',404)
    cart=pos_cart(row)
    if row['status']!='open':raise Problem('This cart is already completed or discarded. Check sales history.',409)
    if d.get('revision')!=row['revision']:raise Problem('This cart changed in another tab. Reload it before continuing.',409)
    if path in ('hold','resume'):
        cart['held']=path=='hold';retail_save_cart(c,cart);retail_event(c,ident,u['name'],path,{})
        return finish({'cart':cart},'POS sale '+path)
    if path=='adjustment-request':
        if not cart['lines']:raise Problem('Add items before requesting an adjustment.')
        mode=d.get('mode')
        if mode not in ('discount','surcharge'):raise Problem('Choose discount or surcharge.')
        amount=pos_int(d.get('amount'),'adjustment',0,10000000);index=d.get('index')
        if index is not None:index=pos_int(index,'line number',0,len(cart['lines'])-1)
        request={'mode':mode,'amount':amount,'index':index,'reason':pos_text(d.get('reason'),'an adjustment reason',300),'requested_by':u['name'],'sale_total':cart['total'],'items':[{'name':l['name'],'quantity':l['quantity'],'subtotal':l['subtotal']} for l in cart['lines']]}
        request['percent_bps']=d.get('percent_bps')
        retail_check_adjustment(c,cart,request)
        if has_permission(u,'approve_pos_adjustments'):
            retail_adjust(c,cart,request,u['name']);return finish({'cart':cart},'POS adjustment approved')
        if c.execute("SELECT 1 FROM retail_adjustments WHERE cart=? AND status='pending'",(ident,)).fetchone():raise Problem('A request is already pending. Ask a manager to review it.',409)
        request_id=c.execute("INSERT INTO retail_adjustments(cart,revision,requested_by,body,status) VALUES(?,?,?,?,'pending')",(ident,cart['revision'],u['name'],json.dumps(request))).lastrowid
        retail_event(c,ident,u['name'],'adjustment-request',request)
        return finish({'approval':request_id},'POS adjustment requested')
    if cart.get('held') and path not in ('discard',):raise Problem('Resume this held sale before changing or completing it.',409)
    if path in ('add','remove'):
        if cart.get('adjustment'):raise Problem('Ask a manager to restore original prices before changing items.',409)
        lines=cart['lines']
        if path=='add':
            if len(lines)>=100:raise Problem('Maximum 100 lines per cart.')
            quantity=pos_int(d.get('quantity'),'quantity',1,999)
            if d.get('product'):
                item=retail_sale_item(c,pos_text(d['product'],'an item identifier',32),d.get('choices',{}),quantity,cart['settings']['tax_bps'],d.get('open_price'))
            else:
                item={'name':pos_text(d.get('name'),'an item name'),'category':pos_text(d.get('category'),'a category',60),'price':pos_int(d.get('price'),'price',1),'taxable':d.get('taxable')}
                if type(item['taxable']) is not bool:raise Problem('Choose taxable or non-taxable.')
                subtotal=item['price']*quantity;item.update(quantity=quantity,subtotal=subtotal,tax=(subtotal*cart['settings']['tax_bps']+5000)//10000 if item['taxable'] else 0)
            lines.append(item)
        else:
            index=pos_int(d.get('index'),'line number',0,len(lines)-1)
            lines.pop(index)
        cart['subtotal']=sum(x['subtotal'] for x in lines);cart['tax']=sum(x['tax'] for x in lines);cart['total']=cart['subtotal']+cart['tax']
        if cart['total']>10000000:raise Problem('Sale exceeds the $100,000 limit.')
        cart['revision']+=1
        body={k:v for k,v in cart.items() if k not in ('id','revision','status')}
        c.execute('UPDATE pos_carts SET body=?,revision=?,updated=? WHERE id=?',(json.dumps(body),cart['revision'],time.time(),ident))
        return finish({'cart':cart},'POS cart changed')
    if path=='discard':
        reason=pos_text(d.get('reason'),'a cancellation reason',300) if cart['lines'] else 'Empty cart'
        retail_event(c,ident,u['name'],'canceled',{'reason':reason,'total':cart['total']})
        c.execute("UPDATE pos_carts SET status='discarded',revision=revision+1 WHERE id=?",(ident,))
        return finish({'ok':True},'POS cart discarded')
    if path=='credit':
        pos_credit_access(u)
        if not has_permission(u,'use_store_credit'):raise Problem('Redeem store credit permission required.',403)
        if not cart['lines'] or cart['total']<=0:raise Problem('Add an item before checkout.')
        account=pos_credit_account(c,pos_int(d.get('account'),'account',1))
        if not account['active']:raise Problem('Account is inactive.',409)
        if d.get('account_revision')!=account['revision']:raise Problem('Balance changed. Refresh the account before paying.',409)
        amount=pos_int(d.get('amount'),'store credit',1,min(account['balance'],cart['total']))
        remaining=cart['total']-amount
        tender=pos_int(d.get('tender'),'cash received',remaining,20000000 if remaining else 0)
        balance=account['balance']-amount
        sale={k:v for k,v in cart.items() if k not in ('id','revision','status')}
        sale.update(**retail_cash_change(cart['settings'],tender,remaining))
        sale.update(at=now,cashier=u['name'],method='store_credit_cash' if remaining else 'store_credit',tender=tender,store_credit=amount,credit_account=account['code'],credit_name=account['name'],credit_balance=balance)
        sale_id=c.execute('INSERT INTO pos_sales(cart,owner,body) VALUES(?,?,?)',(ident,owner,json.dumps(sale))).lastrowid
        c.execute('INSERT INTO pos_credit_ledger(account,amount,balance,at,actor,reason,sale) VALUES(?,?,?,?,?,?,?)',(account['id'],-amount,balance,now,u['name'],'Payment for receipt #'+str(sale_id),sale_id))
        c.execute("UPDATE pos_carts SET status='paid',revision=revision+1 WHERE id=?",(ident,))
        return finish({'sale':dict(id=sale_id,**sale)},'POS store-credit sale completed #'+str(sale_id))
    if path=='cash':
        if not cart['lines'] or cart['total']<0:raise Problem('Add an item before checkout.')
        tender=pos_int(d.get('tender'),'cash received',cart['total'],20000000)
        sale={k:v for k,v in cart.items() if k not in ('id','revision','status')}
        sale.update(**retail_cash_change(cart['settings'],tender,cart['total']))
        sale.update(at=now,cashier=u['name'],method='cash',tender=tender)
        sale_id=c.execute('INSERT INTO pos_sales(cart,owner,body) VALUES(?,?,?)',(ident,owner,json.dumps(sale))).lastrowid
        c.execute("UPDATE pos_carts SET status='paid',revision=revision+1 WHERE id=?",(ident,))
        return finish({'sale':dict(id=sale_id,**sale)},'POS cash sale completed #'+str(sale_id))
    raise Problem('Payment method or action is not available.',400)


