                    if theme not in RETAIL_THEMES and not (scope=='user' and theme=='default'):raise Problem('Choose a listed retail theme.')
                    account='store' if scope=='store' else (u.get('receipt_owner') or 'user:'+u['name'])
                    old=c.execute('SELECT revision FROM retail_theme_preferences WHERE account=?',(account,)).fetchone();revision=old['revision'] if old else 0
                    if d.get('revision')!=revision:raise Problem('Theme settings changed. Close and reopen Appearance.',409)
                    c.execute('INSERT INTO retail_theme_preferences VALUES(?,?,?) ON CONFLICT(account) DO UPDATE SET theme=excluded.theme,revision=excluded.revision',(account,theme,revision+1))
